-- Visit Cambodia public content seed for cambo-turism
-- Re-applies the public catalog and guide content after database reset.

begin;

on conflict (id) do update set slug=excluded.slug,name_km=excluded.name_km,name_en=excluded.name_en,banner_image_url=excluded.banner_image_url;

select setval(pg_get_serial_sequence('public.provinces','id'), greatest((select max(id) from public.provinces), 1));

on conflict (id) do update set slug=excluded.slug,province_id=excluded.province_id,listing_type=excluded.listing_type,business_type=excluded.business_type,publication_status=excluded.publication_status,category=excluded.category,name_km=excluded.name_km,name_en=excluded.name_en,summary_km=excluded.summary_km,summary_en=excluded.summary_en,image_url=excluded.image_url,ticket_usd=excluded.ticket_usd,ticket_status=excluded.ticket_status,ticket_url=excluded.ticket_url,ticket_provider=excluded.ticket_provider,open_hours=excluded.open_hours,access_km=excluded.access_km,access_en=excluded.access_en,source_urls=excluded.source_urls,lat=excluded.lat,lng=excluded.lng,views=excluded.views;

select setval(pg_get_serial_sequence('public.places','id'), greatest((select max(id) from public.places), 1));

on conflict (province_id) do update set overview_km=excluded.overview_km,overview_en=excluded.overview_en,story_km=excluded.story_km,story_en=excluded.story_en,history_km=excluded.history_km,history_en=excluded.history_en,culture_km=excluded.culture_km,culture_en=excluded.culture_en,travel_km=excluded.travel_km,travel_en=excluded.travel_en,attractions_km=excluded.attractions_km,attractions_en=excluded.attractions_en,stay_guide_km=excluded.stay_guide_km,stay_guide_en=excluded.stay_guide_en,food_guide_km=excluded.food_guide_km,food_guide_en=excluded.food_guide_en,source_urls=excluded.source_urls;

on conflict (place_id) do update set about_km=excluded.about_km,about_en=excluded.about_en,history_km=excluded.history_km,history_en=excluded.history_en,highlights_km=excluded.highlights_km,highlights_en=excluded.highlights_en,visit_plan_km=excluded.visit_plan_km,visit_plan_en=excluded.visit_plan_en,tips_km=excluded.tips_km,tips_en=excluded.tips_en,source_urls=excluded.source_urls;

commit;
