(1,'angkor-wat',20,'attraction',NULL,'published','history','ប្រាសាទអង្គរវត្ត','Angkor Wat','មហាសំណង់ប្រាសាទបុរាណធំបំផុតនៅលើពិភពលោក និងជានិមិត្តរូបជាតិនៃប្រទេសកម្ពុជា។','The largest religious monument in the world and the iconic national symbol of Cambodia.',NULL,'37.00',NULL,NULL,NULL,'05:00-17:30',NULL,NULL,'[]'::jsonb,'13.412500','103.867000',1200),
(2,'bayon-temple',20,'attraction',NULL,'published','history','ប្រាសាទបាយ័ន','Bayon Temple','ប្រាសាទថ្មដ៏ល្បីល្បាញដែលមានរូបព្រហ្មមុខបួនញញឹមជាង ២០០ ស្ថិតនៅចំកណ្ដាលក្រុងអង្គរធំ។','Famous temple in Angkor Thom known for its 216 serene, gigantic stone faces.',NULL,'37.00',NULL,NULL,NULL,'07:30-17:30',NULL,NULL,'[]'::jsonb,'13.441400','103.858700',850),
